      "Cook on medium heat on both sides for a few seconds, then smear ghee and cook until golden brown and cooked through completely.Proceed the same way with the remaining portions of the paratha dough.Serve the Methi Lachha Paratha along with Mango Achar, Paneer Butter Masala or your favorite Vegetarian Gravy for a weeknight dinner or even for breakfast along with a chutney."
