      "Add salt only if needed.",
      "Take care that the idlis don't break while tossing.",
      "Saute lightly and turn off heat.To Saute Veggies:In a shallow frying pan, heat a bit of oil and add all the vegetables and saute for 4-5 minutes on low-medium heat or till slightly tender but cooked al dente.",
      "Keep aside.On a wooden skewer, thread a piece of red bell pepper, yellow bell pepper then a green bell pepper, then one mini idli, and again do same ordering for second idli, and arrange them on a serving bowl.To make SambarTo prepare sambar, in a pressure cooker, cook arhar dal with enough water, to about 3 whistles or till mushy.",
