      "Once the naan dough has doubled in size, punch down the dough, knead for a minute and divide into equal portions.Heat a cast iron tawa on medium heat, and keep it ready.Roll out each dough ball into a 4 inch diameter, place the grated cheese, and bring the edges together and make a potli, flatten between your palms, dust it in flour and begin to roll in a way that we get elongated, oval naans.",
