      "Heat a grill pan on medium-high flame, place the marinated chicken pieces and cook for about 3-4 minutes on each side.",
      "Ensuring that the chicken momo filling is cooked.",
      "Turn off the heat, transfer the chicken momo filling into a bowl and set aside.",
      "To make the Tandoori Chicken Momos RecipeTake a bamboo dim sum maker, or the regular idli steamer and fill it with water and pre heat it over a medium heat.Divide the momo dough into equal portions, of lemon sized balls.Take each ball and start rolling it out on a surface.",
