    "title": "Indian Fish Fry",
    "name": "Indian Fish Fry",
    "disease": "Normal",
    "category": "Dinner",
    "mealType": "Dinner",
    "image": "/images/bp/normalpeopledishes/ba5f57930aeaca64ef1607169c5e3f66ae0302b4.jpg",
    "ingredients": [
      "4 Fish - ayala (bangada fish)",
      "1-1/2 tablespoon Red Chilli powder",
      "1/4 teaspoon Turmeric powder (Haldi)",
      "1/2 teaspoon Fennel Powder",
      "1 teaspoon Black pepper powder",
      "1 teaspoon Ginger Garlic Paste",
      "1 teaspoon Lemon juice",
      "Salt - to taste",
      "Sunflower Oil - for shallow fry"
    ],
    "procedure": [
      "To begin making the Ayala Fish Fry Recipe, wash and clean fish well.",
      "Leave it whole.",
      "Score the fish on it’s skin on both sides.In a bowl squeeze lime juice.",
      "Add red chilli powder, turmeric powder, fennel powder, black pepper powder, ginger-garlic paste, salt and mix well.",
      "Make a thick paste.Rub the spice paste all over the fish including the slit areas on both the sides.Cover and let the fish marinate in the fridge for 15 minutes.Heat few tablespoons oil in a pan.",
      "Shallow fry the whole fish on medium flame until golden brown on both sides.Serve hot with lime wedges and onion carrot slices if preferred.Serve Ayala Fish Fry with Mixed Vegetable Sambar, Steamed Rice and Elai Vadam for a weekday lunch or dinner."
    ],
