      "Add in curry leaves.Leave it to crackle, and then add in chopped ginger, garlic and onions and saute until the onions soften have turned to golden brown.Add chopped tomatoes, sprinkle salt and turmeric and saute till the tomatoes turn slightly mushy.Sprinkle the freshly prepared Malvani masala as well and saute for a minute.",
