      "Once it comes to a brisk boil, simmer the Thakali Rasam for 10 minutes on low heat, until you see the Thakali Rasam frothing up.Once you notice the Thakkali Rasam frothing up, turn off the heat.",
      "Finally, garnish the Tomato Rasam with freshly chopped coriander leaves.",
      "Serve the Thakali Rasam along with hot rice, topped with ghee and a Beetroot Curry or Chow-Chow Curry."
