      "Once the sugar has dissolved completely, turn the heat down and allow the mixture to boil for a few minutes till it reaches a one-string consistency.To test if it has reached the right consistency, transfer a few drops of the syrup on a clean plate, allow it to cool for 15-20 seconds and test it for the formation of a single thread between your thumb and index finger.If the syrup has reached single thread consistency, transfer the ground cashew nut powder into the syrup and stir continuously for 4-5 minutes.",
      "The mix will gradually turn into a thick paste.Take the mixture off the heat and allow it to cool to room temperature.",
      "As soon as the mix cools down slightly, grease your palms with a dash of ghee and start kneading the mix.",
      "Knead till it is smooth, uniform and like a dough.Next, spread a sheet of butter paper on the counter top.",
      "Place the dough on it and roll the dough out with a rolling pin to a thickness of 5-6 mm, evenly.Place a saucepan with water on the heat.",
