      "This will help the chocolate solidify.When the chocolate has set, you can cut the Chocolate Kaju Katlis by making intersecting diagonal lines, so they form the trademark diamond shapes.",
      "Serve the Chocolate Kaju Katli Recipe along with Angoori Rasmalai Recipe at a festive gathering with family and friends."
